E('teeth',"Upper teeth: superior alveolar arteries (posterior, middle and anterior, from the maxillary and infraorbital arteries). Lower teeth: inferior alveolar artery (maxillary artery), with its incisive and mental branches.","Alveolar veins to the pterygoid venous plexus and the facial vein.","Upper teeth: posterior, middle and anterior superior alveolar nerves (V2) forming the superior dental plexus. Lower teeth: inferior alveolar nerve (V3) forming the inferior dental plexus. The pulp carries pain fibres only; the periodontal ligament has pressure endings.")
UP="Upper teeth: posterior, middle and anterior superior alveolar arteries (maxillary and infraorbital arteries) enter through the apical foramen."
LO="Lower teeth: inferior alveolar artery (maxillary artery) in the mandibular canal, with incisive and mental branches."
def tooth(i,up,lo,sup,lov):
    E(i,UP+" "+LO if False else up+" "+lo,"Alveolar veins to the pterygoid venous plexus and the facial vein.",sup+" "+lov+" The pulp carries pain fibres only; the periodontal ligament has pressure and position endings.")
for i in ('central-incisor','lateral-incisor','canine'):
    tooth(i,"Upper: anterior superior alveolar artery (infraorbital artery) through the apical foramen.","Lower: incisive branch of the inferior alveolar artery.","Upper: anterior superior alveolar nerve (V2).","Lower: incisive branch of the inferior alveolar nerve (V3).")
for i in ('first-premolar','second-premolar'):
    tooth(i,"Upper: middle superior alveolar artery (infraorbital artery), with the anterior and posterior superior alveolar arteries.","Lower: inferior alveolar artery (mental branch).","Upper: middle superior alveolar nerve (V2).","Lower: inferior alveolar nerve (V3).")
for i in ('first-molar','second-molar','third-molar'):
    tooth(i,"Upper: posterior superior alveolar artery (maxillary artery).","Lower: inferior alveolar artery (maxillary artery) in the mandibular canal.","Upper: posterior superior alveolar nerve (V2).","Lower: inferior alveolar nerve (V3).")
